const CrossMark: React.FC<{ progress: number; color: string }> = ({
  progress,
  color,
}) => {
  const strokeDash = 150;
  // Split progress: 0-0.5 for first line, 0.5-1.0 for second line
  const p1 = interpolate(progress, [0, 0.5], [0, 1], {
    extrapolateRight: "clamp",
  });
  const p2 = interpolate(progress, [0.5, 1], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <svg
      width="240"
      height="240"
      viewBox="0 0 100 100"
      style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: "translate(-50%, -60%)", // slightly up to cover glass body
        overflow: "visible",
      }}
    >
      <line
        x1="10"
        y1="10"
        x2="90"
        y2="90"
        stroke={color}
        strokeWidth="12"
        strokeLinecap="round"
        strokeDasharray={strokeDash}
        strokeDashoffset={strokeDash * (1 - p1)}
      />
      <line
        x1="90"
        y1="10"
        x2="10"
        y2="90"
        stroke={color}
        strokeWidth="12"
        strokeLinecap="round"
        strokeDasharray={strokeDash}
        strokeDashoffset={strokeDash * (1 - p2)}
      />
    </svg>
  );
};

const Sunburst: React.FC<{
  rotation: number;
  scale: number;
  color: string;
}> = ({ rotation, scale, color }) => {
  const rays = new Array(12).fill(0);
  return (
    <div
      style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        width: 800,
        height: 800,
        transform: `translate(-50%, -50%) rotate(${rotation}deg) scale(${scale})`,
        zIndex: -1,
        opacity: Math.min(scale, 0.6), // fade in with scale
      }}
    >
      {rays.map((_, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            width: 800,
            height: 60,
            backgroundColor: color,
            transformOrigin: "center center",
            transform: `translate(-50%, -50%) rotate(${i * 30}deg)`,
            borderRadius: 30,
            filter: "blur(20px)",
          }}
        />
      ))}
    </div>
  );
};

// --- Schema ---


export type MilkComparisonProps = Record<string, any>;

const MilkComparison: React.FC<MilkComparisonProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 6,
  cowMilkColor = "#ffffff",
  plantMilkColor = "#EFE4D0", // Oat color
  glassOutlineColor = "#a0a0a0",
  crossColor = "#FF4444",
  highlightColor = "#FFD700",
  textColor = "#ffffff",
  cowLabel = "Cow Milk",
  plantLabel = "Oat Milk",
}) => {
  useFontLoader(["Inter"]);
  const { fps, width, height } = useVideoConfig();
  const frame = useCurrentFrame();

  const finalBg = transparentBackground ? "transparent" : backgroundColor;

  // --- Timing Config ---
  const entranceStart = 0;
  const crossStart = 25;
  const crossDuration = 20;
  const highlightStart = 50;

  // --- Animations ---

  // 1. Entrance (Slide Up + Fade)
  const entranceProgress = spring({
    frame: frame - entranceStart,
    fps,
    config: { damping: 12 },
  });

  const entranceY = interpolate(entranceProgress, [0, 1], [100, 0]);
  const entranceOpacity = interpolate(entranceProgress, [0, 1], [0, 1]);

  // 2. Cross Out (Cow)
  const crossProgress = interpolate(
    frame,
    [crossStart, crossStart + crossDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.inOut(Easing.ease) }
  );

  // 3. Cow Rejection (Shrink + Fade)
  const cowRejectionScale = interpolate(
    frame,
    [crossStart + crossDuration, crossStart + crossDuration + 20],
    [1, 0.8],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const cowRejectionOpacity = interpolate(
    frame,
    [crossStart + crossDuration, crossStart + crossDuration + 20],
    [1, 0.5],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 4. Plant Highlight (Scale Up + Sunburst)
  const highlightSpring = spring({
    frame: frame - highlightStart,
    fps,
    config: { stiffness: 60, damping: 10 },
  });
  
  const plantScale = interpolate(highlightSpring, [0, 1], [1, 1.4]);
  const sunburstScale = interpolate(highlightSpring, [0, 1], [0, 1.2]);
  const sunburstRotation = frame * 0.5; // continuous rotation

  // Layout calculation
  const centerX = width / 2;
  const spacing = width * 0.25; // Distance from center

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBg,
        fontFamily: "Inter",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <AbsoluteFill
        style={{
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          height: "100%",
        }}
      >
        {/* Left Side: Cow Milk */}
        <div
          style={{
            position: "absolute",
            left: centerX - spacing,
            transform: `translate(-50%, ${entranceY}px) scale(${cowRejectionScale})`,
            opacity: entranceOpacity * cowRejectionOpacity,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}
        >
          <GlassIcon
            color={glassOutlineColor}
            liquidColor={cowMilkColor}
            label={cowLabel}
            textColor={textColor}
          />
          {crossProgress > 0 && (
            <CrossMark progress={crossProgress} color={crossColor} />
          )}
        </div>

        {/* Right Side: Plant Milk */}
        <div
          style={{
            position: "absolute",
            left: centerX + spacing,
            transform: `translate(-50%, ${entranceY}px) scale(${plantScale})`,
            opacity: entranceOpacity,
            zIndex: 10, // Bring to front when expanding
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
          }}
        >
           {/* Sunburst Background behind Plant Milk */}
           <Sunburst 
              rotation={sunburstRotation} 
              scale={sunburstScale} 
              color={highlightColor} 
           />
           
          <GlassIcon
            color={glassOutlineColor}
            liquidColor={plantMilkColor}
            label={plantLabel}
            textColor={textColor}
          />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default MilkComparison;